  ('Wilson Creek Reservoir 11-A', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.24578412617312, 40.78974621436696), 4326)::extensions.geography),
  ('Rockford Lake', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-96.57993596970987, 40.22073876167221), 4326)::extensions.geography)
) AS v(name, category, water_type, coordinates)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.locations l
  WHERE lower(trim(l.name)) = lower(trim(v.name))
    AND ST_DWithin(
      l.coordinates,
      v.coordinates,
      250
    )
);
